"""Actual bounded parser, generated byte offsets, memory peaks and OOM cleanup."""
import json
from pathlib import Path
import re
import subprocess
import sys

import pytest

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / 'tools'))
from build_builtin_bundle import render_bundle, render_data_source


def test_generated_utf8_slices_are_exact_original_packages():
    bundle = render_bundle()
    generated = render_data_source(bundle)
    slices = re.findall(r'\{(\d+)U, (\d+)U\}', generated)
    packages = json.loads(bundle)['components']
    assert len(slices) == len(packages)
    assert 1 <= len(packages) <= 32
    previous = 0
    for (start, length), expected in zip(slices, packages):
        start, length = int(start), int(length)
        assert start >= previous and 0 < length <= 32768
        assert json.loads(bundle.encode()[start:start+length]) == expected
        previous = start + length
    # Escaped quotes/braces and multibyte characters must not change byte offsets.
    unusual = json.dumps({'version': 1, 'components': [
        {'id': 'test', 'widget': {'text': '小狗说“你好” {\\"} 🎲'}}]},
        ensure_ascii=False, separators=(',', ':'))
    source = render_data_source(unusual)
    start, length = map(int, re.search(r'\{(\d+)U, (\d+)U\}', source).groups())
    assert json.loads(unusual.encode()[start:start+length])['id'] == 'test'


def test_generator_rejects_unbounded_or_noncanonical_slice():
    with pytest.raises(ValueError):
        render_data_source(json.dumps({'version': 1, 'components': [{'id': 'x', 'text': 'x'*32768}]}))
    with pytest.raises(ValueError):
        render_data_source('{"version":1,"components":[]}')


def test_real_c_parser_peak_bounds_and_allocation_failures(tmp_path):
    raw = tmp_path / 'bundle.json'
    raw.write_text(render_bundle())
    generated = tmp_path / 'data.c'
    generated.write_text(render_data_source(render_bundle()))
    source = tmp_path / 'test.c'
    source.write_text(r'''
#include <assert.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "pet_p4_builtin_index.h"
typedef union {max_align_t align;size_t bytes;} allocation_t;
static size_t live,peak,allocations;
static long fail_after=-1;
static void *tracked_malloc(size_t n) {
  if (fail_after==0) return NULL;
  if (fail_after>0) --fail_after;
  allocation_t *h=malloc(sizeof(*h)+n);if(!h)return NULL;
  h->bytes=n;live+=n;if(live>peak)peak=live;++allocations;return h+1;
}
static void tracked_free(void *p) {
  if (!p) return;
  allocation_t *h=(allocation_t*)p-1;
  assert(live>=h->bytes);live-=h->bytes;free(h);
}
int main(int argc,char **argv) {
  assert(argc==2);FILE *f=fopen(argv[1],"rb");assert(f);
  char *raw=calloc(1,200000);size_t n=fread(raw,1,199999,f);fclose(f);
  cJSON_Hooks hooks={tracked_malloc,tracked_free};cJSON_InitHooks(&hooks);
  cJSON *whole=cJSON_Parse(raw);assert(whole);size_t full_peak=peak;
  cJSON_Delete(whole);assert(!live);peak=0;
  cJSON *index=cJSON_Parse(pet_p4_builtin_index_json);assert(index);
  cJSON *items=cJSON_GetObjectItemCaseSensitive(index,"components");
  assert((size_t)cJSON_GetArraySize(items)==pet_p4_builtin_slice_count);
  for(size_t i=0;i<pet_p4_builtin_slice_count;++i) {
    cJSON *p=pet_builtin_parse_slice(raw,n,&pet_p4_builtin_slices[i]);assert(p);
    assert(!strcmp(cJSON_GetObjectItemCaseSensitive(p,"id")->valuestring,
      cJSON_GetObjectItemCaseSensitive(cJSON_GetArrayItem(items,(int)i),"id")->valuestring));
    cJSON_Delete(p);
  }
  cJSON_Delete(index);assert(!live);
  printf("host requested-heap peak: whole=%zu indexed=%zu\n",full_peak,peak);
  assert(peak < full_peak/2);
  // All allocation failure points in a real package release partial trees.
  allocations=0;
  cJSON *p=pet_builtin_parse_slice(raw,n,&pet_p4_builtin_slices[0]);assert(p);
  size_t count=allocations;cJSON_Delete(p);assert(!live);
  for(size_t i=0;i<count;++i) {
    fail_after=(long)i;p=pet_builtin_parse_slice(raw,n,&pet_p4_builtin_slices[0]);
    assert(!p);assert(!live);
  }
  fail_after=-1;
  pet_builtin_slice_t bad={UINT32_MAX,1};assert(!pet_builtin_parse_slice(raw,n,&bad));
  bad=(pet_builtin_slice_t){0,UINT32_MAX};assert(!pet_builtin_parse_slice(raw,n,&bad));
  bad=(pet_builtin_slice_t){0,0};assert(!pet_builtin_parse_slice(raw,n,&bad));
  bad=(pet_builtin_slice_t){0,2};assert(!pet_builtin_parse_slice("[]",2,&bad));
  bad=(pet_builtin_slice_t){0,3};assert(!pet_builtin_parse_slice("{}x",3,&bad));
  bad=(pet_builtin_slice_t){0,2};p=pet_builtin_parse_slice("{}x",3,&bad);assert(p);cJSON_Delete(p);
  bad=pet_p4_builtin_slices[0];--bad.length;assert(!pet_builtin_parse_slice(raw,n,&bad));
  assert(!live);free(raw);cJSON_InitHooks(NULL);return 0;
}
''')
    vendor = ROOT / 'tests/vendor/cjson'
    executable = tmp_path / 'parser'
    subprocess.run(['cc', '-std=c11', '-Wall', '-Wextra', '-Werror',
                    '-Wno-error=deprecated-declarations', '-fsanitize=address,undefined',
                    '-I', str(ROOT/'main'), '-I', str(vendor), str(source),
                    str(generated), str(vendor/'cJSON.c'), '-o', str(executable)], check=True)
    subprocess.run([str(executable), str(raw)], check=True)
